import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { fn } from 'storybook/test';
import Popconfirm from './index';

const meta = {
  component: Popconfirm,
  tags: ['ai-generated'],
  args: {
    children: 'Are you sure?',
  },
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => (
    <Popconfirm
      onConfirm={fn()}
      trigger={<button>Delete item</button>}
    >
      Are you sure you want to delete this item?
    </Popconfirm>
  ),
  play: async ({ canvas }) => {
    await expect(
      canvas.getByRole('button', { name: /delete item/i }),
    ).toBeVisible();
  },
};

export const CustomConfirmText: Story = {
  render: () => (
    <Popconfirm
      confirmText="Confirm"
      onConfirm={fn()}
      trigger={<button>Remove</button>}
    >
      This action cannot be undone.
    </Popconfirm>
  ),
  play: async ({ canvas }) => {
    await expect(
      canvas.getByRole('button', { name: /remove/i }),
    ).toBeVisible();
  },
};

export const Opened: Story = {
  render: () => (
    <div style={{ padding: '80px' }}>
      <Popconfirm
        onConfirm={fn()}
        open={true}
        setOpen={() => {}}
        trigger={<button>Action</button>}
      >
        Confirm this action?
      </Popconfirm>
    </div>
  ),
  play: async ({ canvasElement }) => {
    const doc = canvasElement.ownerDocument;
    await waitFor(() => {
      const allButtons = Array.from(doc.querySelectorAll('button'));
      const cancelBtn = allButtons.find((b) => b.textContent === 'Cancel');
      expect(cancelBtn).toBeTruthy();
    });
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect } from 'storybook/test';
import { TextInputWithGlyph } from './index';
import Icon from '../Icon';

const meta = {
  component: TextInputWithGlyph,
  tags: ['ai-generated'],
  args: {
    label: 'Input',
  },
} satisfies Meta<typeof TextInputWithGlyph>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    label: 'Search',
    placeholder: 'Type to search...',
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByLabelText('Search')).toBeVisible();
  },
};

export const WithIcon: Story = {
  render: () => (
    <TextInputWithGlyph
      label="Search with icon"
      placeholder="Search..."
      icon={<Icon glyph="MagnifyingGlass" />}
    />
  ),
  play: async ({ canvas }) => {
    await expect(canvas.getByLabelText('Search with icon')).toBeVisible();
  },
};

export const WithTyping: Story = {
  args: {
    label: 'Username',
    placeholder: 'Enter username',
  },
  play: async ({ canvas, userEvent }) => {
    const input = canvas.getByLabelText('Username');
    await userEvent.type(input, 'hello-world');
    await expect(input).toHaveValue('hello-world');
  },
};

import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, fn, waitFor } from 'storybook/test';
import { TreeSelect, TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
      { title: 'Cherry', value: 'cherry', key: 'cherry' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const TreeSelectWrapper = ({
  tData,
  initialState = [],
  showControls = false,
}: {
  tData: TreeDataEntry[];
  initialState?: string[];
  showControls?: boolean;
}) => {
  const [state, setState] = useState<string[]>(initialState);
  return (
    <TreeSelect
      state={state}
      tData={tData}
      onChange={setState}
      onReset={showControls ? () => setState([]) : undefined}
      onFilter={showControls ? () => {} : undefined}
    />
  );
};

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
  args: {
    state: [],
    tData: sampleData,
    onChange: fn(),
  },
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => <TreeSelectWrapper tData={sampleData} />,
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Vegetables')).toBeVisible();
    await expect(canvas.getByText('Apple')).toBeVisible();
    await expect(canvas.getByText('Carrot')).toBeVisible();
  },
};

export const WithPreselection: Story = {
  render: () => (
    <TreeSelectWrapper
      tData={sampleData}
      initialState={['apple', 'banana']}
    />
  ),
  play: async ({ canvas }) => {
    const appleCheckbox = canvas.getByLabelText('Apple');
    const bananaCheckbox = canvas.getByLabelText('Banana');
    await expect(appleCheckbox).toBeChecked();
    await expect(bananaCheckbox).toBeChecked();
  },
};

export const WithFilterControls: Story = {
  render: () => (
    <TreeSelectWrapper tData={sampleData} showControls />
  ),
  play: async ({ canvas }) => {
    await expect(canvas.getByText('Reset')).toBeVisible();
    await expect(canvas.getByText('Filter')).toBeVisible();
  },
};

export const SelectItem: Story = {
  render: () => <TreeSelectWrapper tData={sampleData} />,
  play: async ({ canvas, userEvent }) => {
    const appleCheckbox = canvas.getByLabelText('Apple');
    await expect(appleCheckbox).not.toBeChecked();
    // Click the label text instead of the input (which has pointer-events: none)
    await userEvent.click(canvas.getByText('Apple'));
    await waitFor(() => {
      expect(canvas.getByLabelText('Apple')).toBeChecked();
    });
  },
};

