 6→
 7→const MockToastProvider: React.FC<{ children: React.ReactNode }> = ({
 8→  children,
 9→}) => {
10→  const toastContext = useMemo(
11→    () => ({
12→      error: (message: React.ReactNode, closable: boolean = true) =>
13→        action('Toast Error')({ closable, message }),
