17→      progress: (
18→        message: React.ReactNode,
19→        progress: number = 0.5,
20→        closable: boolean = true,
21→      ) => action('Toast Progress')({ closable, message, progress }),
22→      success: (message: React.ReactNode, closable: boolean = true) =>
23→        action('Toast Success')({ closable, message }),
